-- dbo.pr_TongHoptblThongkeChiTietSanLuong '20260928'
CREATE  PROCEDURE dbo.pr_TongHoptblThongkeChiTietSanLuong
    @ngay DATE
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @TuNgay  DATETIME = CAST(@ngay AS DATETIME),
            @DenNgay DATETIME = DATEADD(DAY, 1, CAST(@ngay AS DATETIME)),
            @DiaChi  NVARCHAR(200),
            @SoDongLocal INT = 0,
            @SoDongTNG   INT = 0;

    BEGIN TRY
        -- 1. Tạo bảng local nếu chưa có
        IF OBJECT_ID('dbo.tblThongKeChiTietSanLuong', 'U') IS NULL
        BEGIN
            CREATE TABLE dbo.tblThongKeChiTietSanLuong (
                ID           BIGINT IDENTITY(1,1) NOT NULL,
                DiaChi       NVARCHAR(20)   NULL,
                Style_ID     NVARCHAR(200)  NULL,
                Employee_ID  VARCHAR(40)    NOT NULL,
                TenCongDoan  NVARCHAR(100)  NULL,
                Ngay         DATETIME       NOT NULL,
                In_Time      DATETIME       NULL,
                Out_Time     DATETIME       NULL,
                TGHT         INT            NULL,
                isRedo       CHAR(1)        NULL,
                CONSTRAINT PK_tblThongKeChiTietSanLuong PRIMARY KEY NONCLUSTERED (ID)
            );

            CREATE CLUSTERED INDEX CIX_tblTKCTSL_Ngay_NV
                ON dbo.tblThongKeChiTietSanLuong (Ngay, Employee_ID);
        END

        SELECT @DiaChi = DiaChi FROM dbo.tblDiaChi;

        -- 2. Insert vào bảng local
        BEGIN TRAN;

        INSERT INTO dbo.tblThongKeChiTietSanLuong
            (DiaChi, Style_ID, Employee_ID, TenCongDoan, Ngay, In_Time, Out_Time, TGHT, isRedo)
        SELECT @DiaChi, hd.Style_ID, hd.Employee_ID, oc.Description,
               hd.Staging_Time, hd.In_Time, hd.out_time, hd.work_time_sec, hd.is_redo
        FROM dbo.Hanger_Details hd
        LEFT JOIN dbo.Operation_Codes oc ON oc.Operation_Code = hd.Operation_Code
        WHERE hd.Staging_Time >= @TuNgay
          AND hd.Staging_Time <  @DenNgay
          AND hd.out_time IS NOT NULL
          AND NOT EXISTS (SELECT 1 FROM dbo.tblThongKeChiTietSanLuong t
                          WHERE t.Ngay = hd.Staging_Time
                            AND t.Employee_ID = hd.Employee_ID);

        SET @SoDongLocal = @@ROWCOUNT;

        IF @@TRANCOUNT > 0 COMMIT TRAN;

        -- 3. Đồng bộ sang TNG qua linked server
        SELECT Ngay, Employee_ID COLLATE DATABASE_DEFAULT AS Employee_ID
        INTO #DaCoTNG
        FROM TNG.TNG_QLSX.dbo.tblThongKeChiTietSanLuong
        WHERE Ngay >= @TuNgay AND Ngay < @DenNgay
          AND DiaChi COLLATE DATABASE_DEFAULT = @DiaChi;

        INSERT INTO TNG.TNG_QLSX.dbo.tblThongKeChiTietSanLuong
            (DiaChi, Style_ID, Employee_ID, TenCongDoan, Ngay, In_Time, Out_Time, TGHT, isRedo)
        SELECT t.DiaChi, t.Style_ID, t.Employee_ID, t.TenCongDoan,
               t.Ngay, t.In_Time, t.Out_Time, t.TGHT, t.isRedo
        FROM dbo.tblThongKeChiTietSanLuong t
        WHERE t.Ngay >= @TuNgay AND t.Ngay < @DenNgay
          AND NOT EXISTS (SELECT 1 FROM #DaCoTNG x
                          WHERE x.Ngay = t.Ngay
                            AND x.Employee_ID = t.Employee_ID COLLATE DATABASE_DEFAULT);

        SET @SoDongTNG = @@ROWCOUNT;

        DROP TABLE #DaCoTNG;

        SELECT @SoDongLocal AS SoDongInsertLocal, @SoDongTNG AS SoDongDongBoTNG;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRAN;
        IF OBJECT_ID('tempdb..#DaCoTNG') IS NOT NULL DROP TABLE #DaCoTNG;
        DECLARE @msg NVARCHAR(4000) = ERROR_MESSAGE();
        RAISERROR(@msg, 16, 1);
    END CATCH
END
GO

